        text: "遮音性能はD値（Dr値）で評価されます。一般的なオフィスビルの間仕切り壁はD-30〜D-40程度ですが、夜業態ではD-50以上、ライブ演奏がある場合はD-60以上が推奨されます。この性能を確保するためには、壁・天井・床のすべてに対策が必要です。",
