        text: "高い遮音性能を確保する最も効果的な方法は「二重構造」です。既存の壁の内側にもう一枚壁を設け、その間に空気層とグラスウールを挟む二重壁工法が基本です。床についても、コンクリートスラブの上に防振ゴムを敷き、その上にコンクリートを打つ「浮き床」構造が有効です。",
